 }catch(Throwable $e){$_SESSION['app_error']=$e instanceof InvalidArgumentException||$e instanceof RuntimeException?$e->getMessage():'Speichern fehlgeschlagen.';if(!($e instanceof InvalidArgumentException||$e instanceof RuntimeException))error_log('GSZ offer: '.$e->getMessage());}
